import frappe
from frappe import _
def execute(filters=None):
 f=frappe._dict(filters or {});cond=["cl.company=%s"];vals=[f.company]
 if f.project:cond.append("cl.project=%s");vals.append(f.project)
 rows=frappe.db.sql("select ce.parent ledger,ce.reference_doctype,ce.reference_name,ce.source_row,ce.project,ce.budget_line,ce.funding_agreement,ce.donor,ce.base_amount,ce.allocation_percentage,case when ce.cost_distribution_row is not null and (ce.project is null or ce.budget_line is null) then 'Missing Target' when ce.funding_agreement is not null and ce.donor is null then 'Missing Donor' when ce.cost_distribution_row is not null and ce.distribution_snapshot is null then 'Missing Snapshot' else 'Review' end exception from `tabCommitment Entry` ce inner join `tabCommitment Ledger` cl on cl.name=ce.parent where "+" and ".join(cond)+" and ce.cost_distribution_row is not null and ((ce.project is null or ce.budget_line is null) or (ce.funding_agreement is not null and ce.donor is null) or ce.distribution_snapshot is null)",vals,as_dict=True)
 cols=[{"label":_("Ledger"),"fieldname":"ledger","fieldtype":"Link","options":"Commitment Ledger","width":170},{"label":_("Source"),"fieldname":"reference_name","fieldtype":"Dynamic Link","options":"reference_doctype","width":170},{"label":_("Project"),"fieldname":"project","fieldtype":"Link","options":"Project","width":160},{"label":_("Budget Line"),"fieldname":"budget_line","fieldtype":"Link","options":"Budget Line","width":220},{"label":_("Funding Agreement"),"fieldname":"funding_agreement","fieldtype":"Link","options":"Funding Agreement","width":170},{"label":_("Donor"),"fieldname":"donor","fieldtype":"Link","options":"Donor","width":160},{"label":_("Base Amount"),"fieldname":"base_amount","fieldtype":"Currency","width":120},{"label":_("Exception"),"fieldname":"exception","width":150}]
 return cols,rows
